const body = $json.body ?? $json;

const requiredFields = ["feature", "milestone", "fr_ids", "summary", "result"];

for (const field of requiredFields) {
  if (!body[field]) {
    throw new Error(`Missing required field: ${field}`);
  }
}

const createdAt = new Date().toISOString();

const frList = Array.isArray(body.fr_ids)
  ? body.fr_ids.map(id => `- ${id}`).join("\n")
  : "- none";

const nfrList = Array.isArray(body.nfr_ids) && body.nfr_ids.length > 0
  ? body.nfr_ids.map(id => `- ${id}`).join("\n")
  : "- none";

const markdown = `# Evidence — ${body.milestone} ${body.feature}

## Feature
${body.feature}

## Milestone
${body.milestone}

## Linked Functional Requirements
${frList}

## Linked Non-Functional Requirements
${nfrList}

## Result
${body.result}

## Summary
${body.summary}

## Evidence
- Type: ${body.evidence_type ?? "not provided"}
- URL/path: ${body.evidence_url ?? "not provided"}
- Commit: ${body.commit_url ?? "not provided"}

## Lesson Learned
${body.lesson_learned ?? "not provided"}

## Created At
${createdAt}
`;

return [
  {
    json: {
      ok: true,
      message: "Evidence payload formatted",
      markdown
    }
  }
];
